import axios from "axios";

// Dynamic API base URL configuration
const API = axios.create({
    baseURL: process.env.REACT_APP_API_BASE_URL || "http://localhost:3001", // Use environment variable if available
});

// Helper function for token retrieval
const getAuthToken = () => {
    const token = localStorage.getItem("token");
    if (!token) {
        throw new Error("No authorization token found.");
    }
    return token;
};

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    try {
        const token = getAuthToken();
        if (token) {
            req.headers.Authorization = `Bearer ${token}`;
        }
    } catch (err) {
        // If no token is found, handle gracefully
        console.error("Authorization token not found.");
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        if (response.data.token) {
            localStorage.setItem("token", response.data.token);
        }
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error.response?.data || error.message);
        throw new Error("Login failed. Please try again.");
    }
};

// Logout API
export const logout = async () => {
    try {
        const token = getAuthToken(); // Using the helper to fetch token
        const response = await API.post('/api/logout', {}, {
            headers: {
                'Authorization': `Bearer ${token}`,
            },
        });

        localStorage.removeItem("token"); // Remove token after logout
        return response.data.message || 'Logged out successfully';
    } catch (error) {
        console.error('Error logging out:', error.response?.data || error.message);
        throw new Error('Error logging out. Please try again.');
    }
};

// Franchise APIs
export const createFranchise = (data) => API.post("/franchises", data);
export const getFranchises = () => API.get("/franchises");


app.delete('/franchises/:id', authenticate(['admin', 'superadmin']), async (req, res) => {
    const { id } = req.params;
    console.log("Delete request for id:", id); // Debug log
  
    try {
      const franchise = await Franchise.findById(id);
  
      if (!franchise) {
        console.log("Franchise not found for id:", id); // Debug log
        return res.status(404).json({ message: 'Franchise not found' });
      }
  
      if (req.user.role === 'admin' && franchise.admin.toString() !== req.user._id.toString()) {
        console.log("Unauthorized delete attempt by user:", req.user); // Debug log
        return res.status(403).json({ message: 'Admins can only delete their own franchise' });
      }
  
      await Franchise.findByIdAndDelete(id);
      console.log("Franchise deleted successfully for id:", id); // Debug log
      res.status(200).json({ message: 'Franchise deleted successfully' });
    } catch (error) {
      console.error("Error while deleting franchise:", error);
      res.status(500).json({ message: 'Internal server error' });
    }
  });
  
  

export const updateFranchise = (id, data) => API.put(`/franchises/${id}`, data);

// User APIs
export const createUser = (data) => API.post("/users", data);

// Function to get users
export const getUsers = async () => {
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error.response?.data || error.message);
        throw new Error("Error fetching users. Please try again.");
    }
};

// Function to delete a user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error.response?.data || error.message);
        throw new Error("Error deleting user. Please try again.");
    }
};

// Function to update a user by ID
export const updateUser = async (userId, userData) => {
    try {
        const response = await API.put(`/users/${userId}`, userData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error.response?.data || error.message);
        throw new Error("Error updating user. Please try again.");
    }
};

// Exam Data APIs for a franchise
export const updateExamData = async (exam) => {
    const { franchiseId, _id, ...examData } = exam;
    if (!franchiseId || !_id) {
        throw new Error('Invalid franchiseId or examId');
    }
    try {
        return await API.put(`/franchises/${franchiseId}/exam-data/${_id}`, examData);
    } catch (error) {
        console.error("Error updating exam data:", error.response?.data || error.message);
        throw new Error("Error updating exam data. Please try again.");
    }
};

// Get franchises associated with the logged-in user
export const getAssociatedFranchises = async () => {
    try {
        const response = await API.get('/franchises/associated');
        return response.data;
    } catch (error) {
        console.error("Error fetching associated franchises:", error.response?.data || error.message);
        throw new Error("Error fetching associated franchises. Please try again.");
    }
};

// API for managing user exam data for a franchise
export const createUserExamData = async (examData) => {
    const { franchiseId } = examData;
    if (!franchiseId) {
        throw new Error('Franchise ID is required');
    }
    try {
        const response = await API.post(`/franchises/${franchiseId}/exam-data`, examData);
        return response.data;
    } catch (error) {
        console.error("Error creating exam data:", error.response?.data || error.message);
        throw new Error("Error creating exam data. Please try again.");
    }
};

// Delete Exam Data
export const deleteUserExamData = async (franchiseId, examId) => {
    try {
        const response = await API.delete(`/franchises/${franchiseId}/exam-data/${examId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting exam data:", error.response?.data || error.message);
        throw new Error("Error deleting exam data. Please try again.");
    }
};

// Delete exam data for franchise
export const deleteExamData = (franchiseId, examId) =>
    API.delete(`/franchises/${franchiseId}/exam-data/${examId}`);
